// Long-passage reading comprehension: twelve public-domain extracts (verbatim, from Project
// Gutenberg texts; see passages.json) with retrieval, inference, vocabulary-in-context,
// find-and-copy and author's-effect questions, plus one written answer per extract that a
// grown-up marks. Topics are kind 'reading': questions come straight after the passage with
// no learn card first, because answering from the text IS the skill.

import { readFileSync } from 'node:fs';

const PASSAGES = JSON.parse(readFileSync(new URL('./passages.json', import.meta.url), 'utf8'));
const X = (key, context) => ({ passage: (context ? `(${context})\n\n` : '') + PASSAGES[key].passage, passageSource: PASSAGES[key].passageSource });

const mcq = (id, topic, prompt, options, explain, extra = {}) => ({
  id: `english.${id}`, topic: `english.${topic}`, kind: 'mcq', prompt,
  options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra,
});
const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `english.${id}`, topic: `english.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const written = (id, topic, prompt, hints, model, extra = {}) => ({ id: `english.${id}`, topic: `english.${topic}`, kind: 'written', prompt, hints, model, words: [30, 150], ...extra });
const choiceOnly = { formats: ['choice'] };

const SECRET = X('secret', 'Mary has just unlocked a garden that has been shut up for ten years.');
const WILLOWS = X('willows', 'The Mole has left his spring-cleaning and wandered out into the sunshine.');
const TREASURE = X('treasure', 'Jim Hawkins is hiding by the road. The blind pirate Pew has just been abandoned by his gang.');
const WORLDS = X('worlds', 'A huge metal cylinder from Mars has landed on a common near London. A crowd has gathered.');
const ANNE = X('anne', 'Matthew Cuthbert has come to the station to collect an orphan boy to help on his farm. Instead, he finds a girl.');
const RAILWAY = X('railway', 'A landslide has blocked the railway line. Three children know a train is due in a few minutes. Peter has just said that if only they had something red, they could go round the corner and wave it to warn the train.');
const BEAUTY = X('beauty', 'The narrator is a horse, stabled for the night at an inn. Earlier that evening, the hostler sent a young man called Towler, who was smoking a pipe, up through the trapdoor into the hayloft, telling him to “lay down your pipe” first.');
const BOAT = X('boat', 'The narrator and his friends George and Harris are preparing for a boating holiday.');
const OLIVER = X('oliver', 'Oliver is an orphan in a workhouse, where each boy is given just one small bowl of thin gruel at each meal.');
const PSAMMEAD = X('psammead', 'Five children digging in a gravel pit have found something alive in the sand.');
const DARWIN = X('darwin', 'From the travel journal of the young scientist Charles Darwin, who visited the Galapagos Islands in 1835.');
const JABBER = X('jabberwocky');

const topics = [
  { id: 'english.read-mood', title: 'Reading: setting and atmosphere', kind: 'reading', prereqs: ['english.unseen'], batch: 7, intro: 'Two full-page extracts. Read each one slowly, twice. Then the questions ask what happens, what you can work out, and HOW the writer makes you feel it.', teach: 'Explain what “atmosphere” means in a story, and how a writer creates it.', talk: 'Read the first paragraph of her current book aloud together. What mood does it set, and which words do it?' },
  { id: 'english.read-tension', title: 'Reading: tension and suspense', kind: 'reading', prereqs: ['english.read-mood'], batch: 7, intro: 'Writers build tension by slowing down, by holding back information and by choosing frightening details. Watch for short sentences and for what the narrator notices.', teach: 'Explain three ways a writer can build suspense.', talk: 'Ask her about the scariest moment in a book she has read. How did the writer make it scary?' },
  { id: 'english.read-character', title: 'Reading: character and dialogue', kind: 'reading', prereqs: ['english.read-tension'], batch: 7, intro: 'You learn about characters from what they say, how they say it, and what they do under pressure. These extracts are full of talking.', teach: 'Explain how a writer can show what a character is like without telling you directly.', talk: 'Describe someone you both know using only three things they often say.' },
  { id: 'english.read-voice', title: 'Reading: narrators and viewpoint', kind: 'reading', prereqs: ['english.read-character'], batch: 7, intro: 'Who is telling the story changes everything. One of these narrators is a horse; the other thinks he is much better at packing than he really is.', teach: 'Explain the difference between a first-person and a third-person narrator.', talk: 'Ask her to retell a family story from the point of view of the pet (or the car).' },
  { id: 'english.read-classic', title: 'Reading: older fiction', kind: 'reading', prereqs: ['english.read-voice'], batch: 7, intro: 'Victorian and Edwardian writers used long sentences and unusual words, but the ideas are not hard once you slow down. Both of these extracts are funnier than they first look.', teach: 'Explain what “irony” means, using an example.', talk: 'Ask her what Dickens wants us to think of the workhouse masters.' },
  { id: 'english.read-nonfic', title: 'Reading: non-fiction and nonsense', kind: 'reading', prereqs: ['english.read-classic'], batch: 7, intro: 'A real diary from a famous voyage, and a poem made mostly of invented words. Both test whether you can work out meaning from clues.', teach: 'Explain how you can tell what a made-up word means from the words around it.', talk: 'Invent a nonsense word together and use it in three sentences until its meaning is obvious.' },
];

const items = [
  // ===== setting and atmosphere ========================================================
  // The Secret Garden
  fact('rd.sg1', 'read-mood', 'How long has the garden been shut up?', 'ten years', ['a hundred years', 'one winter', 'since Mary was born'], '“I am the first person who has spoken in here for ten years.”', { accept: ['10 years'] }),
  mcq('rd.sg2', 'read-mood', 'How does Mary know the plants on the walls are roses?', [['She had seen many roses in India', true], ['Ben Weatherstaff told her', false, 'Ben is mentioned, but only as someone who COULD tell if the wood is alive.'], ['They are in flower', false, 'There are “neither leaves nor roses on them now”.']], '“Mary Lennox knew they were roses because she had seen a great many roses in India.”', SECRET),
  mcq('rd.sg3', 'read-mood', '“Climbing roses… swung down long tendrils which made light swaying curtains.” What does this comparison suggest about the garden?', [['It feels like a hidden, secret room', true], ['It is tidy and has been well cared for', false, 'The opposite: everything has run wild and tangled.'], ['It is dark, frightening and dangerous', false, 'The words are gentle: “light”, “swaying”, “lovely bridges”.']], 'Curtains belong indoors. Calling the tendrils curtains makes the garden feel like a secret room shut off from the world.', SECRET),
  fact('rd.sg4', 'read-mood', 'Find and copy the one word the writer uses twice to describe the tangled branches that makes the garden look mysterious.', 'hazy', ['matted', 'wintry', 'leafless'], '“a sort of hazy mantle”, “this hazy tangle”. Hazy means misty and unclear, which is why it looks mysterious.'),
  mcq('rd.sg5', 'read-mood', 'Why does Mary whisper and step softly?', [['The garden is so still she fears waking it', true], ['She is hiding from Ben Weatherstaff nearby', false, 'Nobody is chasing her. Look at “as if she were afraid of awakening some one”.'], ['She has a sore throat from the cold wind', false, 'There is no mention of that.']], '“stepping as softly as if she were afraid of awakening some one.” The stillness makes the garden feel asleep.', SECRET),
  mcq('rd.sg6', 'read-mood', 'What is Mary most worried about at the end of the extract?', [['That the whole garden might be dead', true], ['That she will be caught', false, 'She is thinking about the plants, not about being found.'], ['That the robin will fly away', false, 'The robin sits still and looks at her.']], '“Is it all a quite dead garden? I wish it wasn’t.” She cannot see any sign of a leaf-bud.', SECRET),
  written('rd.sg7', 'read-mood', 'How does the writer make the secret garden feel mysterious and still? Write a short paragraph. Use two short quotations.', ['A clear point: the garden feels mysterious, still, asleep…', 'Quotation 1, and what the words make you picture', 'Quotation 2 (perhaps about sound or silence)', 'The effect on Mary, or on you as the reader'], 'The writer makes the garden feel mysterious by describing the tangled roses as a “hazy mantle spreading over everything”. “Hazy” suggests mist, so we cannot see clearly, which is exactly what mysterious means. The stillness is shown through sound: Mary “whispered” and the robin “did not even flutter his wings”. Even the bird is silent, so the garden seems to be holding its breath, asleep for ten years.', SECRET),

  // The Wind in the Willows
  mcq('rd.ww1', 'read-mood', 'The river is described as “this sleek, sinuous, full-bodied animal”. What technique is this?', [['A metaphor: the river is called an animal', true], ['A simile: the river is like an animal', false, 'There is no “like” or “as”. The river IS an animal in these words, which makes it a metaphor.'], ['Alliteration', false, 'There is some (“sleek, sinuous”), but the main technique is comparing the river to an animal.']], 'The river is written about as a living, playful creature. This is personification, a kind of metaphor.', WILLOWS),
  fact('rd.ww2', 'read-mood', 'Find and copy three words from the same sentence that show how the Mole felt about the river.', 'bewitched, entranced, fascinated', ['chasing, chuckling, gripping', 'glints, gleams, sparkles', 'snug, remote, bright'], '“The Mole was bewitched, entranced, fascinated.” Three words that all mean under a spell: the river has enchanted him.', choiceOnly),
  mcq('rd.ww3', 'read-mood', '“chasing and chuckling, gripping things with a gurgle and leaving them with a laugh”. What do the sounds of these words suggest about the river?', [['It is playful and happy', true], ['It is dangerous, angry and violent', false, 'Chuckling and laughing are happy sounds.'], ['It is slow, lazy and half asleep', false, 'The words are full of quick movement: chasing, gripping, fling.']], 'The repeated “ch” and “g” sounds (chasing, chuckling, gripping, gurgle) sound like laughter and bubbling water.', WILLOWS),
  mcq('rd.ww4', 'read-mood', 'The Mole trots beside the river “as one trots… by the side of a man who holds one spell-bound by exciting stories”. What is the river compared to here?', [['A storyteller', true], ['A dog on a lead', false, 'Trotting might make you think of a dog, but read on: the man “holds one spell-bound by exciting stories”.'], ['A small child', false, 'The Mole is the small one here; the river is the grown-up telling stories.']], 'The river “chattered on to him, a babbling procession of the best stories in the world”. It is a storyteller the Mole cannot stop listening to.', WILLOWS),
  mcq('rd.ww5', 'read-mood', 'How does the writer reveal the Water Rat? What is the effect?', [['Bit by bit, so we work it out with the Mole', true], ['All at once, in one sentence, to shock us', false, 'The reveal is slow: “something bright and small seemed to twinkle… then twinkled once more… it winked at him”.'], ['By having the Rat call out a cheerful greeting', false, 'The Rat says nothing in this extract.']], 'The slow reveal, ending in four very short lines, lets us share the Mole’s curiosity until the final “It was the Water Rat!”', WILLOWS),
  fact('rd.ww6', 'read-mood', 'In “fond of a bijou riverside residence”, what does “bijou” most likely mean?', 'small and charming', ['damp and dark', 'expensive and grand', 'old and ruined'], 'The hole is a “snug dwelling-place… for an animal with few wants”. Bijou (from the French for jewel) means small but attractive. It sounds like an estate agent’s advert, which is the joke.', choiceOnly),
  written('rd.ww7', 'read-mood', 'How does Kenneth Grahame make the river seem alive? Write a short paragraph with two quotations.', ['Name the technique (personification / metaphor)', 'Quotation about what the river DOES', 'Quotation about how it SOUNDS', 'What this makes the reader (and the Mole) feel'], 'Grahame uses personification to make the river seem alive. He calls it a “full-bodied animal, chasing and chuckling”, so it moves and laughs like a playful creature rather than just flowing. The sounds of the words help too: “gripping things with a gurgle and leaving them with a laugh” is full of “g” and “l” sounds like bubbling water. This makes the river feel friendly and exciting, which is why the Mole is “bewitched, entranced, fascinated”.', WILLOWS),

  // ===== tension and suspense ===========================================================
  // Treasure Island
  mcq('rd.ti1', 'read-tension', 'Why has Pew been left behind by the other pirates?', [['Jim is not sure: panic, or revenge for his insults', true], ['He chose to stay behind and fight the riders', false, 'He is “groping and calling for his comrades”. He did not choose this.'], ['He could not hear the horses coming up the road', false, 'Pew is blind, not deaf. He hears the horses and runs.']], '“whether in sheer panic or out of revenge for his ill words and blows I know not”. Jim can only guess.', TREASURE),
  fact('rd.ti2', 'read-tension', 'Find and copy the three-word phrase that tells you how Pew moves while searching for his friends.', 'in a frenzy', ['wrong turn', 'full gallop', 'stone dead'], '“tapping up and down the road in a frenzy”. A frenzy is wild, uncontrolled panic.', { accept: ['a frenzy', 'frenzy'] }),
  mcq('rd.ti3', 'read-tension', '“Down went Pew with a cry that rang high into the night.” How does the order of words add to the drama?', [['Starting with “Down” makes the fall sudden', true], ['It makes the sentence longer and slower to read', false, 'The opposite: it is quick and abrupt.'], ['It hides what happens until the very end', false, 'It tells us exactly what happens, as quickly as possible.']], 'Normal order would be “Pew went down”. Starting with “Down” makes us feel the fall happen before we even know who fell.', TREASURE),
  mcq('rd.ti4', 'read-tension', 'How does Jim feel about Pew’s death? What is the evidence?', [['Shocked, not glad: his death is told quietly', true], ['Delighted, because Pew was a cruel villain', false, 'Look at the words chosen: “gently collapsed”. There is no celebration.'], ['Frightened that the pirates will come back', false, 'Nothing in the passage suggests this: the gang has fled, and Jim’s attention is all on Pew.']], 'Pew is a villain, but Stevenson describes his death quietly and even gently, so we feel the horror of it rather than triumph.', TREASURE),
  mcq('rd.ti5', 'read-tension', 'Which words does Pew shout that show he feels betrayed?', [['“not old Pew!”', true], ['“Johnny, Black Dog, Dirk,” and the others', false, 'Those are just the names he calls. The betrayal is in what he begs them.'], ['“in sheer panic”', false, 'That is Jim speaking, not Pew.']], 'He cannot believe his crew would abandon him. Repeating “old Pew” shows his desperation.', TREASURE),
  fact('rd.ti6', 'read-tension', 'What finally kills Pew?', 'he is trampled by a horse', ['a pistol shot from the hedge', 'the revenue officers arrest and hang him', 'he falls into the sea'], '“right under the nearest of the coming horses… the four hoofs trampled and spurned him”.', choiceOnly),
  written('rd.ti7', 'read-tension', 'How does Stevenson make the last moments of Pew dramatic? Write a short paragraph with two quotations.', ['Point: the writer builds panic, then a sudden end', 'Quotation showing Pew’s panic (what he does or shouts)', 'Quotation from the moment of his death, and why the word order or word choice matters', 'How the reader feels: pity? horror?'], 'Stevenson makes Pew’s death dramatic by showing his panic first. He is “tapping up and down the road in a frenzy”, begging “you won’t leave old Pew, mates”, so we see a dangerous man suddenly helpless. Then the death comes in one abrupt sentence: “Down went Pew with a cry that rang high into the night.” Starting with “Down” makes the fall feel sudden and final. The gentle words “gently collapsed… and moved no more” make the reader feel pity, even for a villain.', TREASURE),

  // The War of the Worlds
  mcq('rd.wo1', 'read-tension', 'What did the narrator and the crowd expect to come out of the cylinder?', [['A man, or something like one', true], ['A monster with long grey tentacles', false, 'That is what DOES come out. “I think everyone expected to see a man emerge.”'], ['Nothing at all: they thought it empty', false, 'They had heard it being unscrewed from inside.']], '“I think everyone expected to see a man emerge—possibly something a little unlike us terrestrial men, but in all essentials a man.”', WORLDS),
  mcq('rd.wo2', 'read-tension', '“For a moment that circular cavity seemed perfectly black. I had the sunset in my eyes.” Why does the writer include this?', [['To delay the reveal and build suspense', true], ['To describe the beautiful evening weather', false, 'The sunset matters because it stops him seeing, not because it is pretty.'], ['To show us that the cylinder is empty inside', false, 'He cannot see inside yet; something IS there.']], 'Making the narrator unable to see for a moment holds back the information we are desperate for. That pause is suspense.', WORLDS),
  fact('rd.wo3', 'read-tension', 'What does the narrator first see moving in the shadow of the cylinder?', 'greyish billowy movements', ['two luminous disks', 'a little grey snake', 'a big greyish rounded bulk'], 'The order matters: first “greyish billowy movements”, then “two luminous disks—like eyes”, then the snake-like tentacle. Each detail is clearer and worse than the last.', choiceOnly),
  mcq('rd.wo4', 'read-tension', 'Why does the writer compare the first tentacle to “a little grey snake, about the thickness of a walking stick”?', [['It makes an alien thing easy to picture, and scary', true], ['Because the Martian really is a kind of snake', false, 'It is a tentacle. The comparison helps us picture it.'], ['To make the creature seem small, slow and harmless', false, '“Little” sounds harmless, but snakes are not, and more tentacles follow.']], 'Wells gives us familiar things (a snake, a walking stick, eyes) so we can picture something nobody has ever seen.', WORLDS),
  mcq('rd.wo5', 'read-tension', 'How does the crowd’s reaction change through the extract?', [['From excitement to horror, until people flee', true], ['They stay calm and curious throughout', false, '“There was a loud shriek from a woman behind… I saw astonishment giving place to horror.”'], ['They grow angry and attack the cylinder', false, 'Nobody attacks; they move backwards and run.']], 'The crowd mirrors what we should feel: “astonishment giving place to horror… a general movement backwards… running off”.', WORLDS),
  fact('rd.wo6', 'read-tension', 'Find and copy the two-word phrase that describes the narrator’s fear just before he stands “petrified and staring”.', 'ungovernable terror', ['sudden chill', 'inarticulate exclamations', 'strange horror'], '“ungovernable terror gripped me”. Ungovernable means impossible to control. He cannot make himself move.', { accept: ['terror'] }),
  written('rd.wo7', 'read-tension', 'How does H. G. Wells build suspense as the cylinder opens? Write a short paragraph with two quotations.', ['Point: Wells slows the moment down and holds back what we want to see', 'Quotation showing a delay or something we cannot see yet', 'Quotation showing the first glimpse, revealed bit by bit', 'The effect on the reader'], 'Wells builds suspense by delaying what we want to see. When the lid falls, “that circular cavity seemed perfectly black” because the narrator has “the sunset in my eyes”, so we have to wait. Then the creature is revealed in pieces: “greyish billowy movements”, then “two luminous disks—like eyes”, then “something resembling a little grey snake”. Each detail is clearer and more frightening than the last, so the reader feels the horror growing with the narrator until “ungovernable terror gripped me”.', WORLDS),

  // ===== character and dialogue =============================================================
  // Anne of Green Gables
  mcq('rd.an1', 'read-character', 'What had Anne planned to do if Matthew had not come?', [['Sleep in the wild cherry tree', true], ['Walk to Green Gables', false, 'She mentions the track, but only to reach the tree.'], ['Go back to the orphanage', false, 'She never mentions the orphanage. She planned to wait in the tree, because she was “quite sure you would come for me in the morning”.']], '“I’d go down the track to that big wild cherry-tree at the bend, and climb up into it to stay all night.”', ANNE),
  mcq('rd.an2', 'read-character', 'What do we learn about Anne from how much she talks?', [['She is imaginative and bursting to share her thoughts', true], ['She is rude and does not care what Matthew thinks', false, 'She is polite (“I’m very glad to see you”) and keeps asking “don’t you think?”'], ['She is nervous and shy', false, 'Matthew is the shy one: he speaks “shyly”.']], 'Anne turns everything into a story: a night in a tree becomes “dwelling in marble halls”. She chatters on and keeps asking “don’t you think?” because she longs to share her thoughts with someone.', ANNE),
  mcq('rd.an3', 'read-character', 'Why does Matthew decide not to tell Anne there has been a mistake?', [['He cannot bear to disappoint so happy a child', true], ['He has already decided to keep her', false, 'Not yet. He only decides to “take her home and let Marilla do that”.'], ['He believes there has been no mistake at all', false, 'He knows there has: they asked for a boy.']], '“He could not tell this child with the glowing eyes that there had been a mistake; he would take her home and let Marilla do that.” It shows his kindness and his shyness.', ANNE),
  fact('rd.an4', 'read-character', 'Find and copy the word that tells you how Matthew took Anne’s hand.', 'awkwardly', ['shyly', 'cheerfully', 'gently'], '“Matthew had taken the scrawny little hand awkwardly in his”. He is not used to children.', { accept: ['awkward'] }),
  mcq('rd.an5', 'read-character', '“I’ve got all my worldly goods in it, but it isn’t heavy.” What does this tell you about Anne’s life?', [['She owns almost nothing', true], ['She packs very lightly for holidays', false, 'This is not a holiday: everything she owns fits in one old bag.'], ['She is very strong', false, 'The bag is light because there is so little in it.']], 'A whole life’s belongings in one light carpet-bag. The writer lets us work this out instead of saying “Anne was poor”.', ANNE),
  mcq('rd.an6', 'read-character', 'The writer says Anne spoke in “a peculiarly clear, sweet voice” and Matthew spoke “shyly”. What contrast is being set up?', [['A talkative, confident child and a quiet, awkward man', true], ['A rude child and a strict man', false, 'Neither is rude or strict.'], ['Two people who already know each other well', false, 'They have just met.']], 'The humour and warmth of the scene come from the contrast: Anne fills the silence that Matthew cannot.', ANNE),
  written('rd.an7', 'read-character', 'What impressions do you get of Anne from this extract? Write a short paragraph with two pieces of evidence.', ['Point 1 about Anne (imaginative? talkative? lonely?) + a quotation', 'Point 2 + a quotation', 'Explain what the evidence shows, not just what it says'], 'Anne comes across as hugely imaginative. She plans to sleep in a “wild cherry-tree all white with bloom in the moonshine” and says “You could imagine you were dwelling in marble halls”, so she turns even a night alone into an adventure. She is also brave and hopeful: “I wouldn’t be a bit afraid”, and she was “quite sure you would come for me in the morning”. Her long, excited speech beside Matthew’s few shy words makes her seem bursting with life, which is both funny and touching.', ANNE),

  // The Railway Children
  mcq('rd.rc1', 'read-character', 'Why do the children need something red?', [['Red is the danger signal that tells trains to stop', true], ['So the driver can see them clearly in the dark', false, 'It is not dark. Red matters because on the railway red means danger: stop.'], ['To mark exactly where the landslide has fallen', false, 'Finding the landslide is not the problem; warning the driver before the train reaches it is.']], 'Peter says: “If we only had something red, we could go round the corner and wave to the train.” Red means danger.', RAILWAY),
  mcq('rd.rc2', 'read-character', 'Phyllis stops short and finishes “in quite a different tone”. Why does her tone change?', [['She suddenly realises their petticoats are red', true], ['She is embarrassed to mention their underwear', false, 'A little, perhaps, but the real reason is the idea that strikes her: the petticoats are red.'], ['She is angry that Peter is ordering her about', false, 'Nothing suggests anger.']], 'Her words begin as a complaint about being hot and end as a discovery. Bobbie hears it at once: “Oh, yes… THEY’RE red!”', RAILWAY),
  fact('rd.rc3', 'read-character', 'How many flags do the children make, and how many minutes do they have?', 'six flags, seven minutes', ['three flags, seven minutes', 'six flags, ten minutes', 'two flags, five minutes'], '“Now, we’ve got six flags.” He looked at the watch again. “And we’ve got seven minutes.”', choiceOnly),
  mcq('rd.rc4', 'read-character', 'Which child is most practical in a crisis? What is the evidence?', [['Bobbie: she tears the petticoats and keeps them focused', true], ['Phyllis: she notices the heat and has the idea', false, 'Phyllis hesitates: “you’re not going to TEAR them?”'], ['Peter: he does everything himself, without help', false, 'Peter leads and has the idea, but “you’ll never tear it through the band!” Bobbie does it.']], 'Bobbie sees what matters: “if we can’t stop the train, there’ll be a real live accident, with people KILLED.” Then she acts.', RAILWAY),
  mcq('rd.rc5', 'read-character', 'Why are some words printed in capitals, like “THEY’RE red” and “people KILLED”?', [['To show which word is stressed', true], ['Because they are names of people or places', false, 'They are ordinary words. The capitals show stress.'], ['To mark words the children spelt wrongly', false, 'There are no mistakes. The capitals show how the words are said.']], 'Capitals here work like underlining in speech: they show which word is said loudest. It makes the dialogue sound real and urgent.', RAILWAY),
  fact('rd.rc6', 'read-character', 'Find and copy the phrase that shows Peter speaks sharply to Phyllis when there is no time to argue.', 'with brief sternness', ['at their best pace', 'for some odd reason', 'red-faced and damp'], '“‘Shut up,’ said Peter, with brief sternness.” Brief means short; stern means strict. There is no time to be gentle.', { accept: ['brief sternness'] }),
  written('rd.rc7', 'read-character', 'How does E. Nesbit show that the children are frightened but brave? Write a short paragraph with two quotations.', ['Evidence of fear (look at how the children speak and hesitate)', 'Evidence of bravery or quick thinking', 'How the dialogue makes the scene feel real and urgent'], 'Nesbit shows the children’s fear through their voices: Phyllis “faltered” as she asked “you’re not going to TEAR them?”, and Bobbie cries “Oh, horrible!” at the thought of “people KILLED”. Yet they act bravely. Bobbie says “tear them into little bits if you like”, putting the passengers before her own clothes, and they all ran “at their best pace”. The short, urgent lines of dialogue (“Shut up”, “Now”) make the scene feel fast and real, as if the seven minutes are ticking away for the reader too.', RAILWAY),

  // ===== narrators and viewpoint ==========================================================
  // Black Beauty
  mcq('rd.bb1', 'read-voice', 'The narrator does not know what the “soft rushing sort of noise and a low crackling and snapping” is. Why not, and what is it?', [['He is a horse; it is fire in the hayloft', true], ['He is a sleepy child; it is rain on the roof', false, 'The narrator is in a stall with a halter. He is a horse, and the sound is fire.'], ['He is a traveller; it is horses stamping below', false, 'The stamping is mentioned separately. The rushing and crackling comes from overhead.']], 'Telling the story through a horse means the reader understands the danger before the narrator does. That is what makes it frightening.', BEAUTY),
  mcq('rd.bb2', 'read-voice', 'Why do the horses refuse to leave with the first hostler?', [['His panic makes them more afraid', true], ['They are too sleepy and slow to move', false, '“The other horses were all awake; some were pulling at their halters”.'], ['They cannot see him in the smoky dark', false, 'He has a lantern. The problem is his fear: “so frightened himself that he frightened me still more”.']], '“No doubt we were very foolish, but danger seemed to be all round, and there was nobody we knew to trust in”.', BEAUTY),
  fact('rd.bb3', 'read-voice', 'Find and copy the two words that describe James’s voice when he arrives.', 'quiet and cheery', ['dreadful and roaring', 'strange and uncertain', 'thick and choking'], '“James’ voice, quiet and cheery, as it always was.” The contrast with the panicking hostler is the point.', { accept: ['quiet, cheery', 'cheery'] }),
  mcq('rd.bb4', 'read-voice', 'Why does James tie his scarf over Beauty’s eyes?', [['So the horse cannot see the flames', true], ['To keep the smoke out of the horse’s eyes', false, 'It is “tied lightly over my eyes” so he cannot see the fire; the smoke is everywhere anyway.'], ['As a punishment for refusing to move', false, 'James is “patting and coaxing”, not punishing.']], 'A horse that cannot see the fire can be led past it. James stays calm and thinks of what the horse needs.', BEAUTY),
  mcq('rd.bb5', 'read-voice', 'What is the effect of telling this story from the horse’s point of view?', [['We share the fear of an animal who cannot understand', true], ['It makes the fire seem less serious and frightening', false, 'The opposite: not understanding makes it more frightening.'], ['It lets the narrator explain how the fire started', false, 'The horse cannot explain it. We have to work out that the pipe in the hayloft is the cause.']], 'Anna Sewell wrote the book to make people treat horses kindly. Living inside the horse’s fear is how she does it.', BEAUTY),
  mcq('rd.bb6', 'read-voice', 'What probably started the fire?', [['Towler took his pipe up into the hayloft', true], ['The lantern the hostler carried', false, 'The hostler arrives after the fire has started.'], ['Ginger kicked over a lamp', false, 'Ginger is only mentioned coughing.']], 'The hostler told Towler to “lay down your pipe” before going up to the loft. The smoke comes from the open trapdoor. The writer lets us work it out.', BEAUTY),
  written('rd.bb7', 'read-voice', 'How does Anna Sewell make the fire frightening by telling the story through a horse? Write a short paragraph with two quotations.', ['Point: the narrator does not understand what is happening, and that is frightening', 'Quotation showing the horse’s confusion or senses', 'Quotation showing the fear spreading between horses and people', 'Why the horse’s viewpoint matters'], 'Sewell makes the fire frightening because the horse does not understand it. He wakes “very uncomfortable, though I hardly knew why” and hears “a low crackling and snapping” that he cannot name, so the reader realises it is fire before he does. Fear spreads from the humans: the hostler was “so frightened himself that he frightened me still more”. By keeping us inside the horse’s senses of smoke, sound and a “red light flickering”, Sewell makes us feel how helpless a trapped animal is.', BEAUTY),

  // Three Men in a Boat
  mcq('rd.tm1', 'read-voice', 'The narrator says packing is one of the “many things that I feel I know more about than any other person living”. How should we take this?', [['As a joke at his own expense', true], ['As a plain fact: he really is an expert packer', false, 'Keep reading: he forgets the boots.'], ['As a complaint about his lazy friends', false, 'The complaint comes later. This line is about himself.']], 'The brackets give it away: “(It surprises me myself, sometimes, how many of these subjects there are.)” He is laughing at his own vanity.', BOAT),
  mcq('rd.tm2', 'read-voice', 'What did the narrator actually want when he offered to pack?', [['To give orders while the others did the work', true], ['To do all of the packing himself, quickly', false, '“What I had meant, of course, was, that I should boss the job, and that Harris and George should potter about under my directions”.'], ['To be left alone in peace and quiet', false, 'He is irritated when they leave him to it.']], 'The humour is in the gap between what he said (“leave the whole matter entirely to me”) and what he meant.', BOAT),
  fact('rd.tm3', 'read-voice', 'What does the narrator discover he has forgotten after strapping the bag shut?', 'the boots', ['his toothbrush', 'the pipe', 'the cigar'], '“Ain’t you going to put the boots in?” said Harris.', { accept: ['boots', 'his boots'] }),
  mcq('rd.tm4', 'read-voice', 'Why is the narrator annoyed with Harris?', [['Harris mentioned the boots only once the bag was shut', true], ['Harris packed everything badly and too fast', false, 'Harris did not pack at all.'], ['Harris laughed at him for forgetting things', false, 'That was George. Harris “couldn’t have said a word until I’d got the bag shut”.']], '“That’s just like Harris. He couldn’t have said a word until I’d got the bag shut and strapped, of course.” The narrator blames everyone but himself.', BOAT),
  mcq('rd.tm5', 'read-voice', '“Now, I’m not like that. I can’t sit still and see another man slaving and working. I want to get up and superintend…” What is funny here?', [['He says he is different, then does the same', true], ['He is genuinely very hard-working', false, '“Superintend” and “walk round with my hands in my pockets” is not work.'], ['He is being modest about his own efforts', false, 'He calls it “my energetic nature”, which is the opposite of modest.']], 'The narrator does not realise he has described himself as lazy. The reader sees what he cannot. That gap is called irony.', BOAT),
  fact('rd.tm6', 'read-voice', 'Find and copy one hyphenated word that describes George’s laugh.', 'crack-jawed', ['uncanny readiness', 'noble task', 'idle dream'], '“one of those irritating, senseless, chuckle-headed, crack-jawed laughs of his.” A pile of insulting adjectives, which tells us more about the narrator’s temper than about George.', choiceOnly),
  written('rd.tm7', 'read-voice', 'How does Jerome K. Jerome make the narrator funny? Write a short paragraph with two quotations.', ['Point: the narrator thinks well of himself but keeps proving himself wrong', 'A boastful quotation', 'A quotation where things go wrong or he blames someone else', 'Name the technique: irony, exaggeration, or a gap between what he says and what we see'], 'Jerome makes the narrator funny through irony: he thinks highly of himself while the reader sees the truth. He boasts that packing is something he knows “more about than any other person living”, then forgets the boots. Instead of admitting it he blames Harris: “That’s just like Harris.” He even claims “I can’t sit still and see another man slaving” before describing how he would “walk round with my hands in my pockets” giving orders. The gap between what he says and what he does is the joke.', BOAT),

  // ===== older fiction =====================================================================
  // Oliver Twist
  mcq('rd.ot1', 'read-classic', 'Why does Oliver, rather than another boy, ask for more?', [['The boys drew lots and he lost', true], ['He is the hungriest boy in the room', false, 'They are all starving. “Lots were cast who should walk up to the master… and it fell to Oliver Twist.”'], ['He is the bravest and the oldest', false, 'He is “somewhat alarmed at his own temerity”: he is scared of his own daring.']], '“Lots were cast… and it fell to Oliver Twist.” He has no choice.', OLIVER),
  mcq('rd.ot2', 'read-classic', '“The master was a fat, healthy man; but he turned very pale.” Why does Dickens tell us the master is fat?', [['To contrast him with the starving boys', true], ['To make us like and trust him', false, 'It makes us dislike him: he is well fed while the children starve.'], ['To explain why he suddenly turned pale', false, 'He turns pale from shock, not from being fat.']], 'One short detail does the work of a whole argument. The man in charge of the food is fat; the boys are “desperate with hunger”.', OLIVER),
  mcq('rd.ot3', 'read-classic', 'The adults react to Oliver’s request with “stupefied astonishment”, “horror” and the prediction that he “will be hung”. What is Dickens doing here?', [['Exaggerating it to make the adults ridiculous', true], ['Showing that asking for more was a real crime', false, 'Dickens wants us to see that it is NOT. The reaction is absurd.'], ['Showing how wild and dangerous Oliver is', false, 'Oliver is a small, hungry child with a spoon.']], 'This is irony: treating a tiny request as a monstrous crime shows the adults, not Oliver, as monstrous.', OLIVER),
  fact('rd.ot4', 'read-classic', 'Find and copy the word that means “daring” or “boldness” in “alarmed at his own temerity”.', 'temerity', ['conclave', 'countenance', 'dietary'], 'Temerity is reckless boldness. Oliver is frightened by his own daring.'),
  fact('rd.ot5', 'read-classic', 'What does the master do after Oliver asks a second time?', 'he hits at him with the ladle', ['he gives Oliver more gruel', 'he faints from shock on the floor', 'he sends Oliver to bed with no supper'], '“The master aimed a blow at Oliver’s head with the ladle; pinioned him in his arm; and shrieked aloud for the beadle.”', choiceOnly),
  mcq('rd.ot6', 'read-classic', '“a long grace was said over the short commons”. What is the effect of “long” and “short” here?', [['It mocks plenty of prayer but little food', true], ['It describes how tall and short the masters are', false, 'Grace is the prayer before a meal; commons means food rations.'], ['It shows the boys were grateful for their meal', false, 'The joke is on the adults, who talk at length and give little.']], 'A long prayer over a tiny meal. Dickens packs his anger into a neat contrast.', OLIVER),
  written('rd.ot7', 'read-classic', 'How does Dickens make the reader feel sorry for Oliver and angry at the adults? Write a short paragraph with two quotations.', ['Evidence about Oliver’s hunger or fear', 'Evidence about the adults (their size, their reactions, what they say)', 'Name the technique: contrast, exaggeration or irony', 'What Dickens wants his readers to think about the workhouse'], 'Dickens makes us pity Oliver by showing he is “desperate with hunger, and reckless with misery” and “alarmed at his own temerity”: a frightened child, not a rebel. The adults are made ridiculous through contrast and exaggeration. The master is “a fat, healthy man” while the boys starve, and the gentleman declares “That boy will be hung” simply for asking for more gruel. By treating a tiny request as a terrible crime, Dickens uses irony to show that the cruel ones are the adults who run the workhouse.', OLIVER),

  // Five Children and It
  mcq('rd.fc1', 'read-classic', 'How does the writer make the Psammead easy to picture, even though it is a made-up creature?', [['By comparing each part to a familiar animal', true], ['By giving it a long, scientific description', false, 'There is nothing scientific. The comparisons are to everyday animals.'], ['By describing its bright colours in detail', false, 'Only one colour (brown) is mentioned; the comparisons to animals do the work.']], '“Eyes… like a snail’s eyes… ears like a bat’s ears… body… shaped like a spider’s… hands and feet like a monkey’s.” Each simile adds one part.', PSAMMEAD),
  mcq('rd.fc2', 'read-classic', 'How does the Psammead feel about the children? What is the evidence?', [['Offended that they do not know what it is', true], ['Frightened that the children will hurt it', false, '“Hurt ME! ME frightened? Upon my word!” It is outraged at the idea.'], ['Delighted to meet some human children', false, 'It is “scornful” and its fur stands up “like a cat’s when it is going to fight”.']], 'It cannot believe anyone would not recognise a Psammead: “Well, I knew the world had changed—but—well, really…”', PSAMMEAD),
  fact('rd.fc3', 'read-classic', 'Which child speaks “gently” and “kindly” to the creature?', 'Anthea', ['Jane', 'Cyril', 'Robert'], 'Anthea does the soothing: “She doesn’t mean to be silly,” Anthea said gently.'),
  mcq('rd.fc4', 'read-classic', 'The Psammead asks whether it is “only the rubbish on her head that makes her silly”. What is it talking about, and what does this show?', [['Jane’s hat; it is rude about humans', true], ['Jane’s hair; it is jealous of her curls', false, '“It looked scornfully at Jane’s hat as it spoke.”'], ['Sand on Jane; it is warning her to move', false, 'The sand fell off the Psammead, not Jane.']], 'Insulting a child’s hat the moment it wakes up tells us the Psammead is grumpy, proud and funny.', PSAMMEAD),
  mcq('rd.fc5', 'read-classic', 'The dashes in “Well, I knew the world had changed—but—well, really—do you mean to tell me seriously…” show that the Psammead is…', [['so astonished it splutters', true], ['speaking very slowly and calmly', false, 'Dashes show breaks and restarts, which here mean spluttering shock.'], ['falling back to sleep in the warm sand', false, 'It is wide awake and indignant.']], 'Dashes show speech breaking up. The creature is lost for words at the children’s ignorance.', PSAMMEAD),
  fact('rd.fc6', 'read-classic', 'Find and copy the phrase that compares the Psammead’s fur to another animal’s.', 'like a cat’s when it is going to fight', ['on long horns like a snail’s eyes', 'ears like a bat’s ears', 'hands and feet like a monkey’s'], '“All its fur stood out like a cat’s when it is going to fight.” A simile that shows its temper as well as its looks.', choiceOnly),
  written('rd.fc7', 'read-classic', 'How does E. Nesbit make the Psammead both strange and funny? Write a short paragraph with two quotations.', ['Quotation from the description that makes it strange (a simile)', 'Quotation from its speech that makes it funny (rude, proud, astonished)', 'What the contrast between the two does for the reader'], 'Nesbit makes the Psammead strange through a pile of similes: its eyes are “on long horns like a snail’s eyes” and it can move them “like telescopes”, so we build the creature part by part from animals we know. Then she makes it funny by giving it a personality that does not match its oddness: it is proud and rude, asking whether “the rubbish on her head” makes Jane silly, and splutters “Hurt ME! ME frightened?” A monster that behaves like a grumpy old relative is both strange and comic.', PSAMMEAD),

  // ===== non-fiction and nonsense =========================================================
  // Darwin
  fact('rd.dw1', 'read-nonfic', 'About how much did each of the two tortoises Darwin met weigh?', 'at least two hundred pounds', ['about fifty pounds', 'seven hundred pounds', 'a hundred feet'], '“two large tortoises, each of which must have weighed at least two hundred pounds”. That is over 90 kg.', choiceOnly),
  mcq('rd.dw2', 'read-nonfic', 'Which of these is an opinion rather than a fact?', [['The tortoises seemed like ancient animals', true], ['One tortoise was eating a piece of cactus', false, 'That is something Darwin saw: a fact.'], ['The other gave a deep hiss and drew in its head', false, 'Also observed: a fact.']], '“Seemed to my fancy” signals an impression, not an observation. Antediluvian means from before the Flood: ancient. Good scientists separate what they saw from what they felt.', DARWIN),
  mcq('rd.dw3', 'read-nonfic', 'In “The few dull-coloured birds cared no more for me than they did for the great tortoises”, what does Darwin notice?', [['The birds were not afraid of him at all', true], ['The birds were brightly coloured and noisy', false, 'They are “dull-coloured”.'], ['The birds were pecking at the great tortoises', false, 'They ignored both him and the tortoises.']], 'Animals on remote islands had no fear of humans. This tameness was one of the observations that later fed into Darwin’s ideas about how species change.', DARWIN),
  mcq('rd.dw4', 'read-nonfic', 'What does the second paragraph tell us about the tortoises’ future?', [['They were being hunted and becoming scarce', true], ['They were carefully protected by the islanders', false, 'The islanders ate them: “two days’ hunting giving them food for the rest of the week”.'], ['There were more and more of them every year', false, '“Their numbers have of course been greatly reduced in this island”.']], 'Single ships took “as many as seven hundred”. Darwin records the facts without comment, but the reader can see where this leads.', DARWIN),
  fact('rd.dw5', 'read-nonfic', 'Find and copy the word Darwin uses for the scene that means “gigantic, like something built by giants”.', 'Cyclopean', ['fatiguing', 'intricate', 'antediluvian'], '“the strange Cyclopean scene”. The Cyclopes were giants in Greek myth, so Cyclopean means on a giant scale.', { accept: ['cyclopean'] }),
  mcq('rd.dw6', 'read-nonfic', 'How is a travel journal like this different from a made-up story?', [['It records real things the writer saw for himself', true], ['It has no description of places at all', false, 'There is plenty: “black lava, the leafless shrubs, and large cacti”.'], ['It is written later by someone who was not there', false, 'Darwin was there. “As I was walking along I met…” is first-hand.']], 'This is a first-hand account: Darwin was there, and “I” shows us what he saw and felt. That makes it vivid, but it is still one person’s view.', DARWIN),
  written('rd.dw7', 'read-nonfic', 'What can a reader learn about Darwin himself from this extract? Write a short paragraph with two quotations.', ['Something about how he observes (details, measurements, comparisons)', 'Something about his feelings or imagination', 'Why both matter for a scientist'], 'The extract shows Darwin as a careful observer. He estimates that each tortoise “must have weighed at least two hundred pounds” and notes exactly what each one did: one “stared at me and slowly walked away”, the other “gave a deep hiss”. But he also has imagination: the tortoises “seemed to my fancy like some antediluvian animals”, and he signals with “to my fancy” that this is a feeling, not a fact. Separating what he saw from what he imagined is what makes him a good scientist.', DARWIN),

  // Jabberwocky
  mcq('rd.jb1', 'read-nonfic', 'Even though the words are invented, what happens in the poem?', [['A boy is warned of a monster, kills it, returns', true], ['A Jubjub bird steals a sword and flies off', false, 'The Jubjub bird is only something to “beware”. The hero fights the Jabberwock.'], ['Nothing happens: it is just strange sounds', false, 'There is a clear story: warning, quest, fight, return.']], 'The grammar and the real words carry the story: “Beware… He took his vorpal sword… He left it dead… Come to my arms, my beamish boy!”', JABBER),
  mcq('rd.jb2', 'read-nonfic', '“The Jabberwock, with eyes of flame, / Came whiffling through the tulgey wood”. What kind of word is “tulgey”, and how can you tell?', [['An adjective: it describes the wood', true], ['A verb: it is something the Jabberwock does', false, 'The verb is “came whiffling”. Tulgey comes before “wood”, like “dark wood” or “thick wood”.'], ['A noun: it is the name of the wood', false, 'It has no capital letter and describes the wood.']], 'You can tell a word’s job from its position. Whatever “tulgey” means, it must describe the wood: perhaps thick, dark and tangled.', JABBER),
  mcq('rd.jb3', 'read-nonfic', '“One, two! One, two! And through and through / The vorpal blade went snicker-snack!” What do the sounds of these lines suggest?', [['Quick, sharp sword strokes', true], ['A slow, sad and gentle ending', false, 'The rhythm is fast and the “snicker-snack” is sharp.'], ['Birds singing in the tulgey wood', false, 'The sounds are blade sounds.']], '“Snicker-snack” is onomatopoeia: it sounds like a blade cutting. The repeated “One, two!” beats like sword strokes.', JABBER),
  fact('rd.jb4', 'read-nonfic', 'Find and copy the invented word that describes how the boy went home, which seems to mix “gallop” and “triumph”.', 'galumphing', ['whiffling', 'burbled', 'chortled'], '“He went galumphing back.” Lewis Carroll called these “portmanteau words”: two words packed into one, like a suitcase. Galumphing is now in the dictionary.'),
  mcq('rd.jb5', 'read-nonfic', 'Why does the poem end with the same stanza it began with?', [['It shows the world carrying on as normal', true], ['The poet ran out of new ideas for an ending', false, 'It is deliberate: a frame around the story.'], ['To show that the monster is still alive', false, 'The Jabberwock is dead: “He left it dead, and with its head…”']], 'A repeated opening and closing stanza is called a frame. The slithy toves are still gyring and gimbling; the world has not noticed the hero.', JABBER),
  mcq('rd.jb6', 'read-nonfic', 'Which TWO real words did Lewis Carroll squash together to make “chortled”?', [['chuckle and snort', true], ['chat and startle', false, 'Think about the sound a delighted father makes: half laugh, half snort.'], ['chop and hurtled', false, 'The father is laughing with joy, not chopping.']], 'Chortle is another portmanteau word that escaped into the real dictionary. The father “chortled in his joy”: he chuckled and snorted at once.', JABBER),
  written('rd.jb7', 'read-nonfic', 'How does Lewis Carroll make a poem full of invented words still exciting and easy to follow? Write a short paragraph with two quotations.', ['Point: the real words and the grammar carry the story', 'A quotation where you can tell what an invented word means from its position or sound', 'A quotation where sound makes the action vivid', 'Why the nonsense is fun rather than confusing'], 'Carroll keeps the poem clear by letting the real words carry the story: “Beware the Jabberwock, my son!” tells us there is a monster and a boy, before any nonsense is needed. The invented words sit where ordinary words would, so “the tulgey wood” must be some kind of dark wood, and the sounds tell us the rest. “The vorpal blade went snicker-snack!” sounds like a sword cutting, so we do not need to know what “vorpal” means to feel the fight. The nonsense is fun because we can work it out.', JABBER),
];

// every question shows its extract, including the find-and-copy ones written without it above
const BY_PREFIX = { sg: SECRET, ww: WILLOWS, ti: TREASURE, wo: WORLDS, an: ANNE, rc: RAILWAY, bb: BEAUTY, tm: BOAT, ot: OLIVER, fc: PSAMMEAD, dw: DARWIN, jb: JABBER };
for (const it of items) if (!it.passage) Object.assign(it, BY_PREFIX[it.id.split('.')[2].slice(0, 2)]);

const TOPIC_HOOKS = {
  'english.read-mood': 'Setting = where and when; atmosphere = how it feels. Hunt for weather, light and sound words.',
  'english.read-tension': 'Short sentences, the unknown and a ticking clock: three ways writers wind up tension.',
  'english.read-character': 'Show, don’t tell: characters give themselves away by what they say and do.',
  'english.read-voice': 'First person says “I”: you are inside one head. Third person says “he” or “she”: a narrator watching.',
  'english.read-classic': 'In older writing, read the whole sentence first, then work out strange words from the words around them.',
  'english.read-nonfic': 'Answer with **PEE**: make your Point, give Evidence from the text, Explain it.',
};
for (const t of topics) t.hook = TOPIC_HOOKS[t.id];

export default [{ subject: 'english', deck: 'reading', topics, items }];
